/**
 * Writes the mock QIIME2 BIOM 2.1 dataset to a directory, for uploading to a running MDT by hand.
 *
 *   node scripts/make-biom21-mock.js [target directory]
 *
 * Defaults to testData/biom21-mock, which is gitignored, so the generated files will not be
 * committed by accident.
 *
 * Reuses tests/helpers/biom21.js rather than repeating the layout, so the files produced here are
 * byte-identical to the ones the test suite generates - what you upload is what is being tested.
 * Needs no credentials: the generator touches nothing in config.js.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
    readSpec, writeMockBiom, taxonomyTsv, samplesTsv, sequencesFasta, specIsSelfConsistent,
} from '../tests/helpers/biom21.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '..');

const README = `Mock QIIME2 BIOM 2.1 dataset
============================

SYNTHETIC DATA. Generated by scripts/make-biom21-mock.js from
tests/fixtures/biom21/qiime2-mock.spec.json. The counts, coordinates, sample names and
sequences are invented. Do not treat any of it as observational data, and do not publish it.

It reproduces the HDF5 layout of a real QIIME2 v2023.5 table.biom so that MDT's BIOM 2.1
input path can be tested without redistributing anyone's data.

Upload all four files together:

  table.biom           the matrix and ids only - its metadata groups are empty, as QIIME2
                       leaves them, which is why the other three files are needed
  metadata.tsv         sample metadata, keyed on sample_name
  taxonomy.tsv         taxonomy as taxonomy.qza contains it: Feature ID / Taxon / Confidence
  dna-sequences.fasta  sequences as repseqs.qza contains it, headed by the md5 feature id

What to expect:

  6 taxa x 4 samples, 11 non-zero entries, 1549 reads in total.

  The mapping step needs id columns set to sample_name and Feature ID, and a value for
  target_gene, which is required before processing.

  The fourth sample, MOCK-S04, is in the matrix but deliberately has no row in
  metadata.tsv. That is not a mistake - it reproduces a real QIIME2 export where one of 29
  samples had no metadata - so expect a warning about a sample with no record in the sample
  file, and expect that sample to still appear with a read count and nothing else.
`;

const main = async () => {
    const target = process.argv[2]
        ? path.resolve(process.argv[2])
        : path.join(repoRoot, 'testData', 'biom21-mock');

    const spec = readSpec();
    if (!specIsSelfConsistent(spec)) {
        throw new Error('The spec is not self-consistent: feature ids are not the md5 of their sequences');
    }

    fs.mkdirSync(target, { recursive: true });
    const result = await writeMockBiom(path.join(target, 'table.biom'), spec);
    fs.writeFileSync(path.join(target, 'metadata.tsv'), samplesTsv(spec));
    fs.writeFileSync(path.join(target, 'taxonomy.tsv'), taxonomyTsv(spec));
    fs.writeFileSync(path.join(target, 'dna-sequences.fasta'), sequencesFasta(spec));
    fs.writeFileSync(path.join(target, 'README.txt'), README);

    console.log(`Wrote the mock QIIME2 dataset to ${target}`);
    for (const name of ['table.biom', 'metadata.tsv', 'taxonomy.tsv', 'dna-sequences.fasta', 'README.txt']) {
        const { size } = fs.statSync(path.join(target, name));
        console.log(`  ${name.padEnd(22)} ${size} bytes`);
    }
    console.log(`\n  ${result.observations.length} taxa x ${result.samples.length} samples,`
        + ` ${result.nonZeroEntries} non-zero entries`);
    console.log(`  ${result.samples.length - spec.samples.length} sample(s) deliberately without`
        + ` a metadata row: ${result.samples.filter(s => !spec.samples.some(r => r.sample_name === s)).join(', ')}`);
};

main().catch(error => {
    console.log(error?.message || error);
    process.exitCode = 1;
});
